      list.createEl("li", { text: line });
    if (this.lines.length > PREVIEW_PAGE_SIZE)
      this.contentEl.createEl("p", {
        text: `${this.lines.length - PREVIEW_PAGE_SIZE} \u5176\u4F59\u53D8\u66F4\u5DF2\u5728\u4E0B\u65B9\u5206\u9875\u4E2D\u5217\u51FA.`
      });
